'use strict';
const $=id=>document.getElementById(id);
const titles={overview:['Evidence before a score.','Measure what an integration proves. Keep what is unknown visible.'],corpus:['Inspect the evidence.','Twelve illustrative fixtures. Every score links back to its assumed control outcomes.'],metric:['A score with its blind spots.','Explore how failed and unobserved controls change the result.'],architecture:['Compare the architecture.','A controlled experiment, with no predetermined winner.'],literature:['Build on existing research.','Foundational work, recent benchmarks and primary implementation guidance.'],protocol:['A study we can reproduce.','A staged plan for meaningful findings and controlled collection.']};
let controls=[],fixtures=[],sandbox={};
const fmt=n=>n===null?'—':Math.round(n);
const names={'critical-failure':'Critical failure','insufficient-evidence':'Insufficient evidence','assessed':'Assessed','not-applicable':'Not applicable'};
function view(v){if(!titles[v])throw Error('Unknown view');document.querySelectorAll('.view').forEach(x=>x.hidden=x.id!==v);document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('title').textContent=titles[v][0];$('subtitle').textContent=titles[v][1];$('crumb').textContent=document.querySelector(`nav button[data-view="${v}"] span`).textContent;}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
function makeResults(i){return Object.fromEntries(controls.map((c,j)=>[c.id,{status:i===0?'pass':(i+j)%7===0?'fail':(i+j)%5===0?'unknown':'pass',evidence:`synthetic:F${String(i+1).padStart(2,'0')}:${c.id}`,note:'Illustrative assumption. No live observation or provider execution.'}]))}
function renderRows(){const query=$('search').value.trim().toLowerCase();const rows=fixtures.filter(f=>($('provider').value==='all'||f.provider===$('provider').value)&&($('arch').value==='all'||f.architecture===$('arch').value)&&f.id.toLowerCase().includes(query));$('count').textContent=rows.length+' of 12 illustrative fixtures';$('rows').innerHTML=rows.map(f=>{const s=PIL.score(controls,f.results);return `<tr><td><b>${f.id}</b><small>Synthetic example</small></td><td>${f.provider}<small>${f.architecture}</small></td><td><b>${fmt(s.lower)}–${fmt(s.upper)}</b> / 100</td><td>${fmt(s.coverage)}%</td><td><span class="verdict ${s.gate}">${names[s.gate]}</span></td><td><button class="text-btn inspect" data-id="${f.id}">Inspect →</button></td></tr>`}).join('')||'<tr><td colspan="6">No matching fixtures. Change a filter or search term.</td></tr>';
 document.querySelectorAll('.inspect').forEach(b=>b.onclick=()=>inspect(b.dataset.id));}
function inspect(id){const f=fixtures.find(x=>x.id===id);if(!f)throw Error('Unknown fixture');$('detail').hidden=false;$('detail').innerHTML=`<div class="eyebrow dark">SYNTHETIC EVIDENCE · ${f.id}</div><h2>${f.provider} / ${f.architecture}</h2><p>These labels demonstrate traceability. They are not assessment results.</p><div class="table-wrap"><table><thead><tr><th>Control</th><th>Outcome</th><th>Evidence reference</th></tr></thead><tbody>${controls.map(c=>`<tr><td>${c.title}</td><td>${f.results[c.id].status}</td><td>${f.results[c.id].evidence}</td></tr>`).join('')}</tbody></table></div>`;return {id:f.id,score:PIL.score(controls,f.results),kind:'synthetic-example'};}
function renderScore(){const s=PIL.score(controls,sandbox);$('bounds').textContent=fmt(s.lower)+'–'+fmt(s.upper);$('coverage').textContent=fmt(s.coverage)+'%';$('observed').textContent=s.observed===null?'Unassessed':fmt(s.observed)+'%';$('gate').className='gate '+s.gate;$('gate').textContent=names[s.gate]+(s.criticalFailures.length?' · '+s.criticalFailures.length+' critical control(s) failed':s.criticalUnknown.length?' · critical evidence missing':'');}
function setOutcome(id,status){if(!controls.some(c=>c.id===id)||!['pass','fail','unknown'].includes(status))throw Error('Invalid control or outcome');sandbox[id]={status,evidence:'synthetic:sandbox:'+id};$('outcome-'+id).value=status;renderScore();return PIL.score(controls,sandbox);}
function reset(){sandbox=structuredClone(fixtures[2].results);controls.forEach(c=>$('outcome-'+c.id).value=sandbox[c.id].status);renderScore();}
const papers=[
['2011 · IEEE S&P','How to Shop for Free Online','Foundational analysis of trust and state mismatches between merchants and third-party cashiers. Historical findings do not establish current prevalence.','https://www.microsoft.com/en-us/research/publication/how-to-shop-for-free-online-security-analysis-of-cashier-as-a-service-based-web-stores/'],
['2016 · NDSS','Attack Patterns for Black-Box Security Testing','Pattern-based testing of multi-party web applications. A useful methodological starting point for replay and protocol-state cases.','https://www.ndss-symposium.org/wp-content/uploads/2017/09/attack-patterns-black-box-security-testing-multi-party-web-applications.pdf'],
['2026 · PREPRINT','Alipay-PIBench','Direct related work: nine product projects and 18 coding-agent integration tasks. Differentiate through cross-provider assurance and evidence coverage.','https://arxiv.org/abs/2607.14573'],
['2026 · PREPRINT','Protocol-Level Attacks on Agentic Commerce Platforms','Adjacent work on agentic payment protocols and AIP-Bench. Keep this distinct from ordinary merchant checkout integrations.','https://arxiv.org/abs/2607.21824'],
['IMPLEMENTATION · STRIPE','Fulfillment and webhooks','Provider guidance for reliable payment completion, event verification and repeat delivery. Use current sandbox behavior to check the lab model.','https://docs.stripe.com/payments/checkout/fulfill-orders'],
['IMPLEMENTATION · SQUARE','Validate webhook notifications','Provider-specific origin verification and signature inputs. Do not assume Stripe and Square signatures are interchangeable.','https://developer.squareup.com/docs/webhooks/step3validate'],
['STANDARD · PCI SSC','SAQ A script eligibility','Distinguishes embedded payment forms from redirects for this particular eligibility criterion. It is not a general exemption from PCI obligations.','https://www.pcisecuritystandards.org/faqs/1588/'],
['METHOD · FIRST','CVSS v4.0','Useful for the severity of individual validated findings. Keep separate from integration-wide assurance and evidence coverage.','https://www.first.org/cvss/v4.0/specification-document']];
async function init(){try{const r=await fetch('controls.json');if(!r.ok)throw Error('Unable to load controls');controls=await r.json();fixtures=Array.from({length:12},(_,i)=>({id:'F'+String(i+1).padStart(2,'0'),kind:'synthetic-example',provider:i%2?'Square':'Stripe',architecture:['Hosted','Embedded','Custom'][i%3],results:makeResults(i)}));
$('profile').innerHTML=[['Transaction integrity',0,5],['Event lifecycle',5,7],['Exposure & operations',7,12]].map(([label,a,b])=>`<div class="profile-row"><span>${label}</span><div class="blocks">${controls.slice(a,b).map(c=>`<i class="${fixtures[2].results[c.id].status}" title="${c.title}: ${fixtures[2].results[c.id].status}"></i>`).join('')}</div></div>`).join('');
$('controls').innerHTML=controls.map(c=>`<div class="control"><div><label for="outcome-${c.id}"><b>${c.title}</b></label><small>${c.weight} weight${c.critical?' · Critical gate':''}</small></div><select id="outcome-${c.id}" aria-label="${c.title}"><option value="pass">Pass</option><option value="fail">Fail</option><option value="unknown">Unknown</option></select></div>`).join('');
controls.forEach(c=>$('outcome-'+c.id).onchange=e=>setOutcome(c.id,e.target.value));$('reset').onclick=reset;reset();renderRows();['provider','arch','search'].forEach(id=>$(id).addEventListener('input',renderRows));
$('papers').innerHTML=papers.map(([type,title,desc,url])=>`<article class="panel"><div class="eyebrow dark">${type}</div><h2>${title}</h2><p>${desc}</p><a target="_blank" rel="noopener noreferrer" href="${url}">Read primary source ↗</a></article>`).join('');
$('export').onclick=()=>{const data={metric_version:'0.1',kind:'illustrative-not-observed',controls,fixtures,sandbox:{results:sandbox,score:PIL.score(controls,sandbox)}};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='payment-lab-synthetic-examples.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'set_hypothetical_control',description:'Change an illustrative control outcome in the score sandbox. Does not assess or contact a website.',inputSchema:{type:'object',properties:{control:{type:'string',enum:controls.map(c=>c.id)},status:{type:'string',enum:['pass','fail','unknown']}},required:['control','status'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['control','status'].includes(k)))throw Error('Invalid input');const result=setOutcome(input.control,input.status);view('metric');return result;}});}catch(e){console.warn('Optional agent tool unavailable',e.message);}}
}catch(e){$('subtitle').textContent='Dashboard could not load. Serve this folder over HTTP and reload.';console.error(e);}}
init();
